"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[898],{7557:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the current value without yielding.\\n\\nOn the client, errors if the value hasn\'t arrived yet. Call [Sencha.waitForReplicators] while loading, or use\\n[TemporaryGlobalReplicator:getAsync] or [TemporaryGlobalReplicator:observe] in code that may run earlier.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","source":{"line":125,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"getAsync","desc":"Returns the current value, yielding until it\'s available. The server value always exists, so this only yields on the\\nclient.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","yields":true,"source":{"line":143,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"set","desc":"Sets the value and sends it to every player. Errors if the value doesn\'t match the replicator\'s type. Setting a\\nprimitive to the value it already has does nothing; setting a table always counts as a change.","params":[{"name":"value","desc":"","lua_type":"T"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":161,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"tryUpdate","desc":"Calls `callback` with the current value. If it returns `true` and a new value, the value is set as with\\n[TemporaryGlobalReplicator:set]; if it returns `false`, nothing changes. Returns what `callback` returned first.\\n\\n`callback` must not yield, so nothing else can change the value between reading and setting it.\\n\\n```lua\\nlocal didStart = EventsNetwork.meteorShowerReplicator:tryUpdate(function(isActive)\\n\\tif isActive then\\n\\t\\treturn false\\n\\tend\\n\\treturn true, true\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(value: T) -> (boolean, T?)"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Server"],"source":{"line":188,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"applyIncrementalUpdate","desc":"Applies `patch` to the value with the incremental config\'s `apply`, then sends only the patch to every player.\\nErrors if the patch or the new value doesn\'t match its type, or if the replicator has no incremental config. An\\nempty table patch does nothing.","params":[{"name":"patch","desc":"","lua_type":"P"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":213,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"onChanged","desc":"Calls `callback` when the value changes, not for the initial value.\\n\\nOn the server, the change is sent to clients before `callback` runs, so anything it changes in response reaches\\nclients after the change that caused it.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","source":{"line":255,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"observe","desc":"Calls `callback` with the current value right away if it has arrived (otherwise when it arrives), then on\\nevery change. `oldValue` is the value before the change, or `nil` for the first call.\\n\\n```lua\\nEventsNetwork.meteorShowerReplicator:observe(function(isActive, wasActive)\\n\\tif isActive and wasActive ~= true then\\n\\t\\tprint(\\"a meteor shower started\\")\\n\\tend\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T?) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":289,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"onUpdateReceived","desc":"Calls `callback` for each patch received, after the value is updated. Only replicators with an incremental\\nconfig receive patches; calling this on one without errors.\\n\\nWhole values (the first value, or a `set`) don\'t fire this; use\\n[TemporaryGlobalReplicator:onChanged] to see every change.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T, patch: P) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":311,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"getObservable","desc":"Returns an [ObservableValue](https://jdevon.github.io/observable-value/) that follows the replicated value,\\nfor code that works with ObservableValues, like the\\n[ReactObservableValue](https://github.com/JDevon/react-observable-value) hooks. Calling this again returns the same\\none. Setting it doesn\'t change the replicated value. Errors if the value hasn\'t arrived yet.\\n\\n```lua\\nlocal isMeteorShower = ReactObservableValue.useObservableValue(EventsNetwork.meteorShowerReplicator:getObservable())\\n```","params":[],"returns":[{"desc":"","lua_type":"ObservableValue<T>"}],"function_type":"method","realm":["Client"],"source":{"line":335,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}},{"name":"isLoaded","desc":"Returns whether the value has arrived from the server.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Client"],"source":{"line":351,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}}],"properties":[],"types":[],"name":"TemporaryGlobalReplicator","desc":"One value the server keeps in memory and sends to every player, created with\\n`Sencha.temporaryReplicator.global`. Per-player data never goes through a global replicator unless you put it\\nthere, so the server always chooses what becomes public.","source":{"line":24,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryGlobalReplicator.luau"}}')}}]);